import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { login, register } from '../services/auth';

export default function AuthPage() {
  const [mode, setMode] = useState('login');
  const [role, setRole] = useState('étudiant');
  const [form, setForm] = useState({ 
    nom: '', 
    prenom: '', 
    email: '', 
    password: '', 
    date_naissance: '' 
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login: setUser } = useAuth();
  const navigate = useNavigate();

  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));

  async function handleSubmit(e) {
    e.preventDefault();
    setLoading(true); 
    setError('');

    try {
      let user;
      if (mode === 'login') {
        // --- LOGIQUE CONNEXION ---
        user = await login(form.email, form.password);
      } else {
        // --- LOGIQUE INSCRIPTION ---
        // On prépare un objet propre pour éviter les erreurs 422
        const payload = {
          nom: form.nom,
          prenom: form.prenom,
          email: form.email,
          password: form.password,
          role: role, // 'étudiant' ou 'professeur'
          // On transforme une chaîne vide en null pour la date si nécessaire
          date_naissance: form.date_naissance || null,
          ville: null,  // Sera rempli plus tard dans le profil
          niveau: null  // Sera rempli plus tard dans le profil
        };
        user = await register(payload);
      }

      setUser(user);
      navigate('/');
    } catch (err) {
      // On récupère le message d'erreur précis du Backend
      const msg = err.response?.data?.detail || 'Une erreur est survenue';
      setError(Array.isArray(msg) ? msg[0].msg : msg);
    } finally {
      setLoading(false);
    }
  }

  const inp = { 
    background: 'var(--surface2)', 
    border: '1px solid var(--border)', 
    borderRadius: 10, 
    color: 'var(--text)', 
    padding: '11px 14px', 
    fontSize: '.9rem', 
    width: '100%', 
    outline: 'none' 
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', background: 'var(--bg)' }}>

      {/* SECTION GAUCHE : DESIGN (Inchangé) */}
      <div style={{ flex: 1, background: 'linear-gradient(135deg,#1a1a2e,#16213e,#0f3460)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 24, padding: 60 }}>
        <div style={{ textAlign: 'center', marginBottom: 20 }}>
          <div style={{ fontSize: '3rem', marginBottom: 12 }}>🎓</div>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '2rem', background: 'linear-gradient(90deg,#fff,rgba(255,255,255,.7))', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', marginBottom: 8 }}>EduMatch</div>
          <div style={{ color: 'rgba(255,255,255,.55)', fontSize: '.9rem', maxWidth: 320, textAlign: 'center' }}>La plateforme intelligente qui connecte les meilleurs professeurs avec les étudiants ambitieux</div>
        </div>
        {[
          ['🤖','Chatbot IA pour trouver votre prof idéal'],
          ['⭐','Matching intelligent par score de compatibilité'],
          ['📅','Calendrier de réservation en temps réel'],
          ['🛡️','Professeurs vérifiés et validés']
        ].map(([icon,text]) => (
          <div key={text} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 20px', background: 'rgba(255,255,255,.06)', borderRadius: 12, width: '100%', maxWidth: 400 }}>
            <span style={{ fontSize: '1.4rem' }}>{icon}</span>
            <span style={{ fontSize: '.85rem', color: 'rgba(255,255,255,.8)' }}>{text}</span>
          </div>
        ))}
        <div style={{ color: 'rgba(255,255,255,.3)', fontSize: '.75rem', marginTop: 8 }}>
          💡 Demo admin: admin@edumatch.tn / admin123
        </div>
      </div>

      {/* SECTION DROITE : FORMULAIRE */}
      <div style={{ width: 480, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 60, background: 'var(--surface)' }}>
        <form onSubmit={handleSubmit} style={{ width: '100%', maxWidth: 360 }}>
          <div style={{ fontSize: '2rem', marginBottom: 8 }}>👋</div>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '1.6rem', marginBottom: 4 }}>
            {mode === 'login' ? 'Connexion' : 'Créer un compte'}
          </div>
          <div style={{ color: 'var(--text2)', fontSize: '.85rem', marginBottom: 24 }}>
            {mode === 'login' ? 'Bon retour sur EduMatch !' : 'Rejoignez notre communauté éducative'}
          </div>

          {/* Onglets Login / Register */}
          <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 20 }}>
            {['login','register'].map(m => (
              <div key={m} onClick={() => setMode(m)} style={{ flex: 1, padding: 8, textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.85rem', transition: '.2s', background: mode === m ? '#6c63ff' : 'transparent', color: mode === m ? '#fff' : 'var(--text2)' }}>
                {m === 'login' ? 'Connexion' : 'Inscription'}
              </div>
            ))}
          </div>

          {mode === 'register' && (
            <>
              {/* Sélection du rôle */}
              <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 16 }}>
                {['étudiant','professeur'].map(r => (
                  <div key={r} onClick={() => setRole(r)} style={{ flex: 1, padding: 8, textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.82rem', transition: '.2s', background: role === r ? '#6c63ff' : 'transparent', color: role === r ? '#fff' : 'var(--text2)' }}>
                    {r === 'étudiant' ? '👨‍🎓 Étudiant' : '👨‍🏫 Professeur'}
                  </div>
                ))}
              </div>

              {/* Prénom et Nom */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 16 }}>
                <div>
                  <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Prénom</label>
                  <input style={inp} value={form.prenom} onChange={set('prenom')} placeholder="Ex: Ahmed" required />
                </div>
                <div>
                  <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Nom</label>
                  <input style={inp} value={form.nom} onChange={set('nom')} placeholder="Ex: Zouari" required />
                </div>
              </div>

              {/* Date de Naissance */}
              <div style={{ marginBottom: 16 }}>
                <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Date de naissance</label>
                <input type="date" style={inp} value={form.date_naissance} onChange={set('date_naissance')} required />
              </div>
            </>
          )}

          <div style={{ marginBottom: 16 }}>
            <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Email</label>
            <input style={inp} type="email" value={form.email} onChange={set('email')} placeholder="vous@exemple.tn" required />
          </div>

          <div style={{ marginBottom: 16 }}>
            <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Mot de passe</label>
            <input style={inp} type="password" value={form.password} onChange={set('password')} placeholder="••••••••" required />
          </div>

          {error && <div style={{ background: 'rgba(255,101,132,.1)', border: '1px solid rgba(255,101,132,.3)', borderRadius: 8, padding: '10px 14px', fontSize: '.82rem', color: '#ff6584', marginBottom: 16 }}>⚠️ {error}</div>}

          <button type="submit" disabled={loading} style={{ width: '100%', padding: 13, background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 600, fontSize: '.9rem', cursor: loading ? 'not-allowed' : 'pointer', opacity: loading ? .7 : 1 }}>
            {loading ? '⏳ Traitement...' : mode === 'login' ? 'Se connecter →' : 'Créer mon compte →'}
          </button>

          <div style={{ textAlign: 'center', marginTop: 16, fontSize: '.8rem', color: 'var(--text2)' }}>
            {mode === 'login' ? 'Pas encore de compte ? ' : 'Déjà membre ? '}
            <span onClick={() => setMode(mode === 'login' ? 'register' : 'login')} style={{ color: '#6c63ff', cursor: 'pointer', fontWeight: 600 }}>
              {mode === 'login' ? "S'inscrire" : 'Se connecter'}
            </span>
          </div>
        </form>
      </div>
    </div>
  );
}
